        .welcome-animation { display: inline-block; transform-origin: left center; animation: welcome-arrive .85s cubic-bezier(.2,.8,.2,1) both; }
        .welcome-animation::after { content: ' ✦'; display: inline-block; color: #ffd878; font-size: .72em; vertical-align: top; animation: welcome-sparkle .85s ease-out both; }
        @keyframes welcome-arrive { 0% { opacity: 0; transform: translateY(18px) scale(.94); } 65% { opacity: 1; transform: translateY(-3px) scale(1.02); } 100% { opacity: 1; transform: none; } }
        @keyframes welcome-sparkle { 0%, 35% { opacity: 0; transform: scale(.4) rotate(-35deg); } 70% { opacity: 1; transform: scale(1.25) rotate(12deg); } 100% { opacity: .85; transform: scale(1) rotate(0); } }
        @keyframes logout-exit { to { opacity: 0; transform: translateY(12px) scale(.985); filter: blur(3px); } }
        @keyframes logout-sidebar { to { opacity: .25; transform: translateX(-18px); } }
        .app-shell.logging-out { animation: logout-exit .42s ease-in both; pointer-events: none; }
        .app-shell.logging-out .sidebar { animation: logout-sidebar .42s ease-in both; }
