        @media (max-width: 800px) { .sidebar { width: 72px; flex-basis: 72px; } .brand { justify-content: center; padding: 0; font-size: 0; } .brand::after { content: 'LB'; font-size: 17px; } .nav-label, .nav a span:not(.nav-icon), .logout span:not(.nav-icon) { display: none; } .nav a, .logout { justify-content: center; } .stats { grid-template-columns: repeat(2, 1fr); } .weather-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
        @media (max-width: 520px) { .topbar { padding: 0 16px; } .content { padding: 24px 16px; } .stats { gap: 10px; } .stat { padding: 14px; } .content-head { display: block; } .dashboard-lower { grid-template-columns: 1fr; } .weather-search div { max-width: none; flex-direction: column; } .weather-search button { width: 100%; } .weather-summary { flex-direction: column; align-items: flex-start; } .weather-grid { grid-template-columns: 1fr; } .weather-forecast { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
